    "landing.howItWorks.resolve.body": "तुमची तक्रार थेट तुमच्या वॉर्डाची जबाबदारी असलेल्या व्यक्तीपर्यंत, त्यांच्या स्वतःच्या भाषेत पोहोचते.",
    "landing.howItWorks.reassign.title": "त्यांना घेता आले नाही, तर दुसरा कोणीतरी घेतो",
    "landing.howItWorks.reassign.body": "तुमच्या नेमलेल्या कामगाराने ती नाकारल्यास, तुमची तक्रार आपोआप तुमच्या वॉर्डातील पुढील उपलब्ध कामगाराकडे पुन्हा सोपवली जाते — तुम्हाला कधीही पुन्हा सादर करावी लागत नाही.",
    "landing.howItWorks.rate.title": "ट्रॅक करा, मग रेटिंग द्या",
    "landing.howItWorks.rate.body": "ती दाखल झाल्यापासून ते निकाली निघेपर्यंत प्रत्यक्ष वेळेत पाहा, आणि पूर्ण झाल्यावर अभिप्राय द्या.",
    "landing.features.eyebrow": "प्रत्यक्ष वापरासाठी तयार केलेले",
    "landing.features.title": "नागरी तक्रारीसाठी आवश्यक असलेली प्रत्येक गोष्ट",
    "landing.features.languages.title": "6 भाषा",
    "landing.features.languages.body": "इंग्रजी, हिंदी, मराठी, ओडिया, गुजराती आणि बंगाली — तुम्हाला सर्वात सोयीची वाटणारी भाषा, कधीही निवडा.",
    "landing.features.voice.title": "टाइप करण्याऐवजी बोला",
    "landing.features.voice.body": "तुमची तक्रार आवाजाने रेकॉर्ड करा — लांब रेकॉर्डिंग सुद्धा आपोआप हाताळली जाते, पडद्यामागे विभागली जाते आणि लिखित स्वरूपात आणली जाते.",
    "landing.features.photo.title": "एक फोटो जोडा",
    "landing.features.photo.body": "समस्येचा फोटो, ती सोडवणाऱ्या कामगाराला पोहोचण्यापूर्वी नेमके काय हाताळायचे आहे हे समजून घेण्यास मदत करतो.",
    "landing.features.tracking.title": "थेट ट्रॅक करा",
    "landing.features.tracking.body": "तुमची तक्रार सादर झाल्यापासून ते सुटेपर्यंत फॉलो करा, ती कोणाला नेमून दिली आहे ते पहा, आणि पूर्ण झाल्यावर अभिप्राय द्या.",
    "landing.finalCta.title": "काही तक्रार नोंदवायला तयार आहात?",
    "landing.finalCta.body": "यासाठी एक मिनिटापेक्षाही कमी वेळ लागतो, तुम्हाला सोयीच्या असलेल्या कोणत्याही भाषेत.",
    "landing.footer.tagline": "नगरपालिका तक्रार निवारण, प्रत्येक भाषेत.",
