    "landing.login": "ଲଗ୍ ଇନ୍ କରନ୍ତୁ",
    "landing.signup": "ସାଇନ୍ ଅପ୍ କରନ୍ତୁ |",
    "hero.headline": "ଏହାକୁ ତୁମ ଭାଷାରେ ରିପୋର୍ଟ କର। ଏହା ସେମାନଙ୍କ ଭାଷାରେ ପଢ଼ାଯାଏ।",
    "hero.sub": "JanSarthi AI ଆପଣଙ୍କ ସ୍ୱରକୁ ଏକ ଅଭିଯୋଗରେ ପରିଣତ କରେ ଯାହା ଆପଣଙ୍କ ସ୍ଥାନୀୟ କର୍ମଚାରୀ ପଢିପାରିବେ - ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଅନୁବାଦ କରାଯାଏ, ଆପଣ ଦୁହିଁଙ୍କ ମଧ୍ୟରୁ ଯିଏ ବି କେଉଁ ଭାଷା କୁହନ୍ତୁ ନା କାହିଁକି।",
    "hero.cta.primary": "ଆରମ୍ଭ କରନ୍ତୁ |",
    "hero.cta.secondary": "ଲଗ୍ ଇନ୍ କରନ୍ତୁ",
    "landing.howItWorks.eyebrow": "ଏହା କିପରି କାମ କରେ",
    "landing.howItWorks.title": "ରିପୋର୍ଟରୁ ସମାଧାନ ପର୍ଯ୍ୟନ୍ତ। କୌଣସି ସାଝା ଭାଷାର ଆବଶ୍ୟକତା ନାହିଁ।",
    "landing.howItWorks.speak.title": "କୁହନ୍ତୁ କିମ୍ବା ଟାଇପ୍ କରନ୍ତୁ",
    "landing.howItWorks.speak.body": "ସମସ୍ୟାକୁ ଯେପରି ସହଜ ହୁଏ ବର୍ଣ୍ଣନା କରନ୍ତୁ — ଆପଣଙ୍କ ଫୋନରେ କୁହନ୍ତୁ କିମ୍ବା ଟାଇପ୍ କରନ୍ତୁ, ଆମର 6 ଭାଷାରୁ ଯେକୌଣସିଟିରେ ଆପଣ ସହଜ ଅନୁଭବ କରନ୍ତି।",
    "landing.howItWorks.translate.title": "AI ଏହାକୁ ସଫା କରେ ଏବଂ ଅନୁବାଦ କରେ",
    "landing.howItWorks.translate.body": "ଆପଣଙ୍କ ଶବ୍ଦଗୁଡ଼ିକ ଲିପିବଦ୍ଧ, ବନାନ-ଯାଞ୍ଚ ଏବଂ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଅନୁବାଦ ହୁଏ — ଆପଣଙ୍କ କିମ୍ବା ଏହା ପଢୁଥିବା କର୍ମଚାରୀଙ୍କ ପାଇଁ କୌଣସି ମାନୁଆଲ ପାହାଚ ନାହିଁ।",
    "landing.howItWorks.resolve.title": "ସଠିକ୍ କର୍ମଚାରୀ ଏହା ପାଆନ୍ତି",
    "landing.howItWorks.resolve.body": "ଆପଣଙ୍କ ଅଭିଯୋଗ ସିଧାସଳଖ ଆପଣଙ୍କ ୱାର୍ଡର ଦାୟିତ୍ୱରେ ଥିବା ବ୍ୟକ୍ତିଙ୍କ ପାଖକୁ, ସେମାନଙ୍କ ନିଜ ଭାଷାରେ ପହଞ୍ଚେ।",
    "landing.howItWorks.reassign.title": "ସେ ନେଇ ନ ପାରିଲେ, ଅନ୍ୟ ଜଣେ ନିଅନ୍ତି",
    "landing.howItWorks.reassign.body": "ଯଦି ଆପଣଙ୍କ ନିଯୁକ୍ତ କର୍ମଚାରୀ ଏହାକୁ ପ୍ରତ୍ୟାଖ୍ୟାନ କରନ୍ତି, ଆପଣଙ୍କ ଅଭିଯୋଗ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଆପଣଙ୍କ ୱାର୍ଡର ପରବର୍ତ୍ତୀ ଉପଲବ୍ଧ କର୍ମଚାରୀଙ୍କୁ ପୁନଃ ନ୍ୟସ୍ତ ହୁଏ — ଆପଣଙ୍କୁ କେବେ ବି ପୁଣି ଦାଖଲ କରିବାକୁ ପଡ଼ିବ ନାହିଁ।",
    "landing.howItWorks.rate.title": "ଟ୍ରାକ୍ କରନ୍ତୁ, ତାପରେ ମୂଲ୍ୟାଙ୍କନ କରନ୍ତୁ",
    "landing.howItWorks.rate.body": "ଏହା ଦାଖଲରୁ ସମାଧାନ ପର୍ଯ୍ୟନ୍ତ ପ୍ରକୃତ ସମୟରେ ଦେଖନ୍ତୁ, ଏବଂ ସମାପ୍ତ ହେଲେ ମତାମତ ଦିଅନ୍ତୁ।",
