    "landing.howItWorks.translate.title": "AI તેને સાફ કરે છે અને અનુવાદ કરે છે",
    "landing.howItWorks.translate.body": "તમારા શબ્દો લિપિબદ્ધ, જોડણી-તપાસેલ અને આપમેળે અનુવાદિત થાય છે — તમારા માટે કે તેને વાંચનાર કામદાર માટે કોઈ મેન્યુઅલ પગલું નથી.",
