    "landing.howItWorks.resolve.body": "તમારી ફરિયાદ સીધી તમારા વોર્ડની જવાબદારી સંભાળતી વ્યક્તિ સુધી, તેમની પોતાની ભાષામાં પહોંચે છે.",
    "landing.howItWorks.reassign.title": "તેઓ ન લઈ શકે તો, બીજું કોઈ લે છે",
    "landing.howItWorks.reassign.body": "જો તમારા સોંપાયેલા કામદારે તેને નકારી, તો તમારી ફરિયાદ આપમેળે તમારા વોર્ડના આગલા ઉપલબ્ધ કામદારને ફરીથી સોંપાય છે — તમારે ક્યારેય ફરીથી સબમિટ કરવાની જરૂર નથી.",
